from qa import *
a = S(); a.login(*PW["admin"]); t1 = S(); t1.login(*PW["T1"])
log("==== TC-020 re-run 2 (amount = available 11900; earlier W7 100 paid by the pay-vs-cancel thread)", datetime.datetime.now().isoformat())
c, j = a.get("/payroll/balances/?teacher=7"); avail = j[0]["available_minor"]; log("before", short(j))
res = par([lambda: t1.post("/payroll/withdrawals/", {"amount_minor": avail, "currency": "EGP"}) for _ in range(5)])
codes = sorted(r[0] for r in res); chk(f"5 parallel {avail}: exactly one 201, rest 409", codes == [201, 409, 409, 409, 409], str(codes) + " " + str([r[1].get("code") for r in res if r[0] != 201]))
s = q("select coalesce(sum(amount_minor),0) from payroll_withdrawalrequest where teacher_id=1 and status in ('under_review','approved','paid')"); chk("sum reserved+paid <= 20000", int(s) <= 20000, s)
w = [r[1]["id"] for r in res if r[0] == 201][0]; a2 = S(); a2.login(*PW["admin"])
res = par([lambda: a.post(f"/payroll/withdrawals/{w}/approve/"), lambda: a2.post(f"/payroll/withdrawals/{w}/reject/", {"office_notes": "race"})])
log("approve vs reject", [(r[0], r[1].get("status") or r[1].get("code")) for r in res]); chk("approve vs reject one winner one 409", sorted(r[0] for r in res) == [200, 409])
a.post(f"/payroll/withdrawals/{w}/cancel/"); c, j = a.get("/payroll/balances/?teacher=7"); chk("available never negative", j[0]["available_minor"] >= 0, short(j))
save("tc020.txt")
c, raw = a.get("/payroll/payslips/?format=csv", raw=True); h = raw.splitlines()[0]; log("CSV header", h)
chk("TC-021 acknowledgement column in CSV", "cknowledg" in h or "Confirmed" in h, h[-200:]); save("tc021.txt")
